-- Banco Cálculo II v3 — lote 01: 50 questões autorais com auditoria de formatação.
-- Execute os cinco lotes na ordem antes de considerar a substituição concluída.
begin;

-- Mantém tentativas antigas, mas retira o banco anterior da prática pública.
update public.questions set publication_status = 'draft' where subject_id = '20000000-0000-4000-8000-000000000001' and publication_status = 'published' and coalesce(source_id::text, '') not in ('10000000-0000-4000-8000-000000000261', '10000000-0000-4000-8000-000000000262', '10000000-0000-4000-8000-000000000263', '10000000-0000-4000-8000-000000000264', '10000000-0000-4000-8000-000000000265');

values ('10000000-0000-4000-8000-000000000261', 'original', 'Arc original Cálculo II — banco v3, lote 01', 'Questões autorais da Arc. O livro de referência foi usado apenas para mapear competências, dificuldade e variedade de formatos; nenhum enunciado ou solução foi transcrito.', 'Arc', 'approved', 'Equipe editorial Arc', '2026-09-09T00:00:00Z')
on conflict (id) do update set label=excluded.label, licence_note=excluded.licence_note, rights_status=excluded.rights_status, verified_by=excluded.verified_by, verified_at=excluded.verified_at;



















































commit;
